import { useState } from 'react';

export type Filters = { query: string; onlyOpen: boolean };
export type Item = { id: string; title: string; open: boolean };
export type Props = { items: Item[]; onApply: (filters: Filters) => void };

export function Component({ items, onApply }: Props) {
  const empty: Filters = { query: '', onlyOpen: false };
  const [draft, setDraft] = useState<Filters>(empty);
  const [applied, setApplied] = useState<Filters>(empty);

  // 공백만 다른 초안은 변경으로 보지 않지만, 대소문자 변경은 적용할 수 있다.
  const dirty = draft.query.trim() !== applied.query
    || draft.onlyOpen !== applied.onlyOpen;

  function apply() {
    const next: Filters = { ...draft, query: draft.query.trim() };
    setDraft(next);
    setApplied(next);
    onApply(next);
  }

  function reset() {
    setDraft(empty);
    setApplied(empty);
    onApply(empty);
  }

  // 초안 편집과 목록 표시를 분리하고, 항상 최신 items에 적용값을 사용한다.
  const query = applied.query.toLowerCase();
  const visible = items.filter(item =>
    item.title.toLowerCase().includes(query)
    && (!applied.onlyOpen || item.open)
  );

  return (
    <section aria-label="Issue filters">
      <label>
        Search issues
        <input
          value={draft.query}
          onChange={event => setDraft({ ...draft, query: event.currentTarget.value })}
        />
      </label>
      <label>
        <input
          type="checkbox"
          checked={draft.onlyOpen}
          onChange={event => setDraft({ ...draft, onlyOpen: event.currentTarget.checked })}
        />
        Only open
      </label>
      <button type="button" disabled={!dirty} onClick={apply}>Apply</button>
      <button type="button" onClick={reset}>Reset</button>
      <ul aria-label="Issues">
        {visible.map(item => <li key={item.id}>{item.title}</li>)}
      </ul>
      {visible.length === 0 && <p role="status">No issues</p>}
    </section>
  );
}
```

`<Component items={items} onApply={handleApply} />`로 사용하세요. Reset은 현재 값과 관계없이 두 상태를 초기화하고 한 번 통지합니다. 배열은 `filter`로 새로 만들며 부모 데이터를 수정하지 않습니다.

실행·테스트하지 않았습니다. Apply 전 목록 유지, 공백 정리, 검색과 체크의 AND 조건, 공백만 바뀐 초안의 버튼 비활성화, Reset의 콜백 1회, 부모 목록 갱신 시 기존 적용값 유지를 확인하세요.

task:
TypeScript/React 합성 미니 컴포넌트 과제: 첨부 삭제를 원래 위치로 한 번 복원하기
환경: React 19.3.0, TypeScript 5.9.3(strict), react-dom/client, JSDOM 20.0.3. 설치된 React 이외 새 패키지는 사용하지 않는다. Component.tsx에서 named export Component와 Props를 제공한다. 추가 소스 파일은 상대 경로로만 참조한다. 파일 또는 변경 위치를 식별할 수 있게 답한다. 표시 문자열과 접근 가능한 이름은 아래 영문 그대로 사용한다.

계약:
type Item = { id: string; label: string };
type Props = { initialItems: Item[]; onChange: (items: Item[]) => void };

요구사항:
1. 제공된 삭제 취소 버그를 고친다. initialItems는 고유 id를 가진 초기 첨부 목록이며 마운트 이후 동기화는 요구하지 않는다. Attachments라는 이름의 ul에 현재 순서대로 표시한다.
2. 각 항목의 삭제 버튼 접근 가능한 이름은 Remove {label}이다. 클릭한 ID 항목만 제거하고 새 목록으로 onChange를 정확히 한 번 호출한다. 부모가 준 배열/항목 객체를 직접 변경하지 않는다.
3. Undo 버튼은 아직 취소할 삭제가 없으면 disabled이다. 마지막 삭제의 항목과 그 삭제 직전 위치를 기억한다. Undo는 그 위치에 항목을 복원하고 복원된 순서의 새 목록으로 onChange를 정확히 한 번 호출한다.
4. 취소 기록은 한 단계다. 연속 삭제하면 가장 최근 삭제만 복원할 수 있으며, 한 번 Undo 후에는 다시 disabled이다. 이미 없어진 이전 삭제까지 되돌리거나 중복 항목을 추가하지 않는다.
5. 빈 목록에는 No attachments 상태 메시지를 표시한다. 초기 마운트는 콜백을 호출하지 않는다.

제공 파일 Component.tsx:
```tsx
import { useState } from 'react';

export type Item = { id: string; label: string };
export type Props = { initialItems: Item[]; onChange: (items: Item[]) => void };

export function Component({ initialItems, onChange }: Props) {
  const [items, setItems] = useState(initialItems);
  const [removed, setRemoved] = useState<{ item: Item; index: number } | null>(null);
  function remove(id: string) {
    const index = items.findIndex(item => item.id === id);
    if (index < 0) return;
    const next = items.filter(item => item.id !== id);
    setRemoved({ item: items[index], index });
    setItems(next);
    onChange(next);
  }
  function undo() {
    if (!removed) return;
    const next = [...items];
    next.push(removed.item);
    setItems(next);
    setRemoved(null);
    onChange(next);
  }
  return <section aria-label="Attachment list">
    <ul aria-label="Attachments">{items.map(item => <li key={item.id}>{item.label}<button type="button" aria-label={`Remove ${item.label}`} onClick={() => remove(item.id)}>Remove</button></li>)}</ul>
    {items.length === 0 && <p role="status">No attachments</p>}
    <button type="button" disabled={!removed} onClick={undo}>Undo</button>
  </section>;
}
```

